package com.novara.banking.loan;

import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.util.*;
import com.novara.banking.loan.LoanModels.Installment;

@Service public class LoanEmiCalculator {
 private static final MathContext MC=new MathContext(34,RoundingMode.HALF_EVEN);private static final BigDecimal BP=new BigDecimal("10000");private static final BigDecimal MONTHS=new BigDecimal("12");
 public Calculation calculate(long principalMinor,int annualRateBasisPoints,int installments,LocalDate firstDueDate){if(principalMinor<=0||annualRateBasisPoints<0||installments<=0)throw new IllegalArgumentException("Valid positive loan terms are required.");BigDecimal principal=BigDecimal.valueOf(principalMinor);BigDecimal monthly=BigDecimal.valueOf(annualRateBasisPoints).divide(BP,MC).divide(MONTHS,MC);long emi;if(monthly.signum()==0)emi=principal.divide(BigDecimal.valueOf(installments),0,RoundingMode.HALF_EVEN).longValueExact();else{BigDecimal factor=BigDecimal.ONE.add(monthly).pow(installments,MC);emi=principal.multiply(monthly,MC).multiply(factor,MC).divide(factor.subtract(BigDecimal.ONE),MC).setScale(0,RoundingMode.HALF_EVEN).longValueExact();}List<Installment> schedule=new ArrayList<>();long opening=principalMinor,totalInterest=0,totalRepayment=0;for(int sequence=1;sequence<=installments;sequence++){long interest=BigDecimal.valueOf(opening).multiply(monthly,MC).setScale(0,RoundingMode.HALF_EVEN).longValueExact();long scheduledPrincipal=sequence==installments?opening:Math.min(opening,Math.max(1,emi-interest));long due=Math.addExact(scheduledPrincipal,interest);long closing=opening-scheduledPrincipal;schedule.add(new Installment(sequence,firstDueDate.plusMonths(sequence-1),opening,scheduledPrincipal,interest,0,due,closing,"ILLUSTRATIVE"));totalInterest=Math.addExact(totalInterest,interest);totalRepayment=Math.addExact(totalRepayment,due);opening=closing;}if(opening!=0)throw new IllegalStateException("Schedule did not amortize to zero.");return new Calculation(emi,totalInterest,totalRepayment,List.copyOf(schedule));}
 public record Calculation(long emiMinor,long totalInterestMinor,long totalRepaymentMinor,List<Installment> schedule){}
}
